  function render(){const r=route();const base=['flow','packet'].includes(r.name)?'traffic':r.name==='process'?'applications':r.name==='finding'?'security':r.name==='file'?'files':r.name==='case'?'cases':r.name==='alert'?'alerts':r.name==='interface'?'interfaces':r.name==='asset'?'assets':r.name;setActiveNav(base);try{switch(r.name){case'overview':renderOverview();break;case'security':renderSecurity();break;case'traffic':renderTraffic();break;case'applications':renderApplications();break;case'interfaces':renderInterfaces();break;case'hunt':renderHunt();break;case'investigation':renderInvestigation();break;case'cases':renderCases();break;case'case':renderCaseDetail(decodeURIComponent(r.parts[1]||''));break;case'threat-intel':renderThreatIntel();break;case'lab':renderLab();break;case'replay':renderReplay();break;case'sensors':renderSensors();break;case'files':renderFiles();break;case'file':renderFileDetail(decodeURIComponent(r.parts[1]||''));break;case'c2':renderC2();break;case'exposure':renderExposure();break;case'fleet':renderFleet();break;case'streaming':renderStreaming();break;case'analyst':renderAnalyst();break;case'alerts':renderAlerts();break;case'stories':renderStories();break;case'workspace':renderWorkspace(decodeURIComponent(r.parts[1]||''));break;case'quality':renderQuality();break;case'automation':renderAutomation();break;case'performance':renderPerformance();break;case'mitre':renderMitre();break;case'assets':renderAssets();break;case'asset':renderAssetDetail(decodeURIComponent(r.parts.slice(1).join('/')||''));break;case'time-machine':renderTimeMachine();break;case'tuning':renderTuning();break;case'operations':renderOperations();break;case'account':renderAccount();break;case'system':renderSystem();break;case'flow':renderFlowDetail(decodeURIComponent(r.parts[1]||''));break;case'packet':renderPacketDetail(decodeURIComponent(r.parts[1]||''));break;case'process':renderProcessDetail(r.parts[1]||'0');break;case'finding':renderFindingDetail(decodeURIComponent(r.parts[1]||''));break;case'alert':renderAlertDetail(decodeURIComponent(r.parts[1]||''));break;case'interface':renderInterfaceDetail(r.parts.slice(1).join('/'));break;default:location.hash='#/overview'}}catch(e){console.error(e);page.innerHTML=pageHead('Rendering error','The console could not render this view.')+`<section class="panel">${empty('Unexpected UI error',e.message||String(e))}</section>`}}

  function protocolData(flows){const m=new Map();flows.forEach(f=>{const k=protoName(f),v=n(f.bytes_tx)+n(f.bytes_rx);m.set(k,(m.get(k)||0)+v)});return [...m.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6)}
  function drawProtocolDonut(flows){const c=$('protocolChart'),legend=$('protocolLegend');if(!c||!legend)return;const rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr);const x=c.getContext('2d');x.scale(dpr,dpr);const data=protocolData(flows),total=Math.max(1,data.reduce((a,b)=>a+b[1],0)),colors=['#2563eb','#0891b2','#159b62','#7556d8','#d68a00','#dc3f4b'];let start=-Math.PI/2;const cx=rect.width/2,cy=rect.height/2,r=Math.min(rect.width,rect.height)*.42;x.clearRect(0,0,rect.width,rect.height);if(!data.length){x.strokeStyle='#e8edf3';x.lineWidth=18;x.beginPath();x.arc(cx,cy,r,0,Math.PI*2);x.stroke();legend.innerHTML='<span class="td-sub">No classified traffic yet</span>';return}data.forEach(([name,val],i)=>{const a=val/total*Math.PI*2;x.strokeStyle=colors[i];x.lineWidth=19;x.beginPath();x.arc(cx,cy,r,start,start+a);x.stroke();start+=a});legend.innerHTML=data.map(([name,val],i)=>`<div class="legend-row"><i class="swatch" style="background:${colors[i]}"></i><span>${esc(name)}</span><strong>${Math.round(val/total*100)}%</strong></div>`).join('')}
  function drawRiskTrend(findings){const c=$('riskTrendChart');if(!c)return;const rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=Math.max(1,Math.round(rect.width*dpr));c.height=Math.max(1,Math.round(rect.height*dpr));const x=c.getContext('2d');x.scale(dpr,dpr);const w=rect.width,h=rect.height,p={l:42,r:12,t:15,b:27},W=w-p.l-p.r,H=h-p.t-p.b,now=Date.now(),bucket=2*3600*1000,bins=Array.from({length:12},(_,i)=>({t:now-(11-i)*bucket,v:0}));const weight={critical:10,high:6,medium:3,low:1,info:.25};findings.forEach(f=>{const age=now-new Date(f.time).getTime(),idx=11-Math.floor(age/bucket);if(idx>=0&&idx<bins.length)bins[idx].v+=weight[String(f.severity||'').toLowerCase()]||1});const max=Math.max(1,...bins.map(b=>b.v));x.clearRect(0,0,w,h);x.strokeStyle='#e8eef6';x.fillStyle='#8190a5';x.font='10px system-ui';x.textAlign='right';for(let i=0;i<5;i++){const y=p.t+H*i/4;x.beginPath();x.moveTo(p.l,y);x.lineTo(w-p.r,y);x.stroke();x.fillText(Math.round(max*(1-i/4)),p.l-7,y+3)}const g=x.createLinearGradient(0,p.t,0,p.t+H);g.addColorStop(0,'rgba(213,61,86,.22)');g.addColorStop(1,'rgba(213,61,86,0)');x.beginPath();bins.forEach((b,i)=>{const px=p.l+i/(bins.length-1)*W,py=p.t+H-b.v/max*H;i?x.lineTo(px,py):x.moveTo(px,py)});x.strokeStyle='#d53d56';x.lineWidth=2.4;x.stroke();x.lineTo(p.l+W,p.t+H);x.lineTo(p.l,p.t+H);x.closePath();x.fillStyle=g;x.fill();x.fillStyle='#8190a5';x.textAlign='left';x.fillText('24h weighted risk pressure',p.l,h-5)}
  function drawConfidenceDonut(conf){const c=$('confidenceChart');if(!c)return;const rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr);const x=c.getContext('2d');x.scale(dpr,dpr);const data=[conf.high||0,conf.medium||0,conf.low||0],colors=['#159b62','#d18a08','#6f7f93'],total=Math.max(1,data.reduce((a,b)=>a+b,0)),cx=rect.width/2,cy=rect.height/2,r=Math.min(rect.width,rect.height)*.42;x.clearRect(0,0,rect.width,rect.height);let start=-Math.PI/2;data.forEach((v,i)=>{const a=v/total*Math.PI*2;x.strokeStyle=colors[i];x.lineWidth=20;x.lineCap='round';x.beginPath();x.arc(cx,cy,r,start,start+a);x.stroke();start+=a});if(data.every(v=>!v)){x.strokeStyle='#e8eef6';x.lineWidth=20;x.beginPath();x.arc(cx,cy,r,0,Math.PI*2);x.stroke()}}



  async function createCase(finding){if(!finding)return;try{const c=await api('/api/v1/cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({finding_id:finding,window_minutes:10})});state.cases=null;state.detailCache.set('case:'+c.id,c);toast('Incident case created',c.id,'ok');location.hash='#/case/'+encodeURIComponent(c.id)}catch(e){toast('Case creation failed',e.message,'err')}}
  async function addCaseNote(id){const text=$('caseNoteText')?.value?.trim(),author=$('caseNoteAuthor')?.value?.trim();if(!text)return;try{const c=await api(`/api/v1/cases/${encodeURIComponent(id)}/notes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({author,text})});state.detailCache.set('case:'+id,c);state.cases=null;renderCaseDetail(id);toast('Note added','','ok')}catch(e){toast('Could not add note',e.message,'err')}}
  async function activeBlock(ip){if(!ip)return;const body={action:'block_ip',ip,ttl_seconds:900,reason:'NetProbe Security Finding'};try{const r=await api('/api/v1/response',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast(r.dry_run?'Response dry-run':'IP blocked',r.message,'ok')}catch(e){if(/confirm must be APPLY/i.test(e.message)&&confirm(`Apply a live 15-minute block for ${ip}?`)){try{body.confirm='APPLY';const r=await api('/api/v1/response',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});toast('Response applied',r.message,'ok')}catch(x){toast('Response failed',x.message,'err')}}else toast('Response unavailable',e.message,'err')}}

  async function requestBlock(ip){if(!ip)return;try{const r=await api('/api/v1/approvals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'block_ip',ip,ttl_seconds:900,reason:'NetProbe Security Finding'})});state.soc.approvals=undefined;toast('Response approval requested',r.id||ip,'ok')}catch(e){toast('Approval request failed',e.message,'err')}}
  async function lockCase(id){if(!id||!confirm('Lock this case evidence? Locked cases cannot be modified.'))return;try{const c=await api(`/api/v1/cases/${encodeURIComponent(id)}/lock`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});state.detailCache.set('case:'+id,c);state.cases=null;renderCaseDetail(id);toast('Case locked','Evidence is now immutable.','ok')}catch(e){toast('Case lock failed',e.message,'err')}}
  async function addSuppression(){const kind=$('supKind')?.value,value=$('supValue')?.value?.trim(),reason=$('supReason')?.value?.trim(),raw=$('supExpiry')?.value;if(!value)return toast('Suppression value required','','err');const expires_at=raw?new Date(raw).toISOString():undefined;try{await api('/api/v1/tuning',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,value,reason,expires_at})});state.soc.tuning=undefined;renderTuning();toast('Suppression created',`${kind}:${value}`,'ok')}catch(e){toast('Suppression failed',e.message,'err')}}
