    const cert=$('syslogClientCert')?.value?.trim()||'',key=$('syslogClientKey')?.value?.trim()||'';if((cert&&!key&&!state.soc.syslogEdit?.has_client_key)||(!cert&&key))return toast('mTLS configuration incomplete','Client certificate and private key must be configured together.','err');
    const q={id,name:$('syslogName')?.value?.trim(),enabled:$('syslogEnabled')?.checked,host,port,transport,format:$('syslogFormat')?.value,framing:$('syslogFraming')?.value,facility:n($('syslogFacility')?.value),severity:n($('syslogSeverity')?.value),hostname:$('syslogHostname')?.value?.trim(),queue_size:n($('syslogQueue')?.value),categories:[...document.querySelectorAll('.syslog-cat:checked')].map(x=>x.value),tls:{insecure_skip_verify:$('syslogInsecure')?.checked,ca_file:$('syslogCA')?.value?.trim(),server_name:$('syslogServerName')?.value?.trim(),client_cert_file:cert,client_key_file:key}};
