  function acceptData(d){if(!d)return;state.connected=true;if(d.status)state.data.status=d.status;if(Array.isArray(d.flows))state.data.flows=d.flows;if(Array.isArray(d.packets))state.data.packets=d.packets;if(Array.isArray(d.processes))state.data.processes=d.processes;if(Array.isArray(d.alerts))state.data.alerts=d.alerts;if(Array.isArray(d.findings))state.data.findings=d.findings;if(d.traffic_live)appendTrafficLive(d.traffic_live);updateChrome();const r=route();const renderCurrentRoute=()=>{if(route().name===r.name)render()};if(r.name==='overview'){const now=Date.now();if(now-state.overviewLastRender>5000){state.overviewLastRender=now;clearTimeout(state.renderTimer);state.renderTimer=setTimeout(renderCurrentRoute,100)}else requestAnimationFrame(drawLiveTraffic);return}if(['security','traffic','applications','interfaces','hunt','alerts'].includes(r.name)){clearTimeout(state.renderTimer);state.renderTimer=setTimeout(renderCurrentRoute,120)}}
