  // v1.0 investigation, notifications and traffic workspace -----------------
  function graphQueryURL(){const f=state.graphView.filters||{},p=new URLSearchParams();[['q',f.q],['src',f.src],['dst',f.dst],['asset',f.asset],['proto',f.proto],['port',f.port],['app',f.app],['severity',f.severity]].forEach(([k,v])=>{if(String(v||'').trim())p.set(k,String(v).trim())});const ranges={"15m":15*60,"1h":3600,"24h":86400};if(ranges[f.range])p.set('from',new Date(Date.now()-ranges[f.range]*1000).toISOString());if(state.graphView.focusID){p.set('focus',state.graphView.focusID);p.set('neighbors',String(state.graphView.neighbors||2))}if(state.graphView.expandedCluster)p.set('expand',state.graphView.expandedCluster);p.set('max_nodes','800');p.set('max_edges','3000');return '/api/v1/graph?'+p.toString()}
  async function reloadGraph(reset=false){if(state.loading.has('graph-v10'))return;state.loading.add('graph-v10');try{state.graph=await api(graphQueryURL());if(reset){state.graphView.scale=1;state.graphView.ox=0;state.graphView.oy=0;state.graphView.selected=[];state.graphView.selectedEdge=null}if(route().name==='investigation')renderInvestigation()}catch(e){toast('Graph load failed',e.message,'err')}finally{state.loading.delete('graph-v10')}}
  function graphColor(n){if(n.risk>=80)return'#d53d56';if(n.risk>=50)return'#d18a08';return({process:'#2463eb',flow:'#0f9bb8',ip:'#5f7087',domain:'#7556d8',tls:'#0f9f6d',interface:'#475569',finding:'#d53d56',file:'#a855f7',hash:'#64748b',yara:'#dc2626',cluster:'#334155'}[n.type]||'#718096')}
  function graphRadius(n){return n.type==='cluster'?24:n.type==='finding'?13:n.type==='process'?12:n.type==='flow'?10:9}
  function graphHash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
  function ensureGraphPositions(){const g=state.graph;if(!g?.nodes)return;const pos=state.graphView.positions;const by={};g.nodes.forEach(n=>(by[n.type]??=[]).push(n));const rings={process:150,finding:230,flow:340,domain:450,tls:520,ip:590,interface:650,file:420,hash:500,yara:300,cluster:420};Object.entries(by).forEach(([type,xs])=>xs.forEach((n,i)=>{if(pos[n.id])return;const h=graphHash(n.id),ang=(Math.PI*2*(i+(h%97)/97))/Math.max(1,xs.length)-Math.PI/2,r=(rings[type]||480)+(h%31)-15;pos[n.id]={x:720+Math.cos(ang)*r,y:470+Math.sin(ang)*Math.min(r,400)}}))}
  function graphVisible(){const g=state.graph||{nodes:[],edges:[]},hidden=state.graphView.hidden||{},ids=new Set(g.nodes.filter(n=>!hidden[n.id]).map(n=>n.id)),collapsed=state.graphView.collapsed||{};const edges=(g.edges||[]).filter(e=>ids.has(e.from)&&ids.has(e.to)&&!collapsed[e.from]&&!collapsed[e.to]);return{nodes:g.nodes.filter(n=>ids.has(n.id)),edges}}
  function graphScreen(p){const v=state.graphView;return{x:p.x*v.scale+v.ox,y:p.y*v.scale+v.oy}}
  function graphWorld(x,y){const v=state.graphView;return{x:(x-v.ox)/v.scale,y:(y-v.oy)/v.scale}}
  function graphHitNode(sx,sy){const v=graphVisible();for(let i=v.nodes.length-1;i>=0;i--){const n=v.nodes[i],p=graphScreen(state.graphView.positions[n.id]||{x:0,y:0}),r=graphRadius(n)*state.graphView.scale+6;if((p.x-sx)**2+(p.y-sy)**2<=r*r)return n}return null}
  function segDist(px,py,x1,y1,x2,y2){const dx=x2-x1,dy=y2-y1,l=dx*dx+dy*dy;if(!l)return Math.hypot(px-x1,py-y1);let t=((px-x1)*dx+(py-y1)*dy)/l;t=Math.max(0,Math.min(1,t));return Math.hypot(px-(x1+t*dx),py-(y1+t*dy))}
  function graphHitEdge(sx,sy){const v=graphVisible();for(let i=v.edges.length-1;i>=0;i--){const e=v.edges[i],a=graphScreen(state.graphView.positions[e.from]||{}),b=graphScreen(state.graphView.positions[e.to]||{});if(segDist(sx,sy,a.x,a.y,b.x,b.y)<6)return e}return null}
  function fitGraph(selectedOnly=false){const c=$('graphCanvas');if(!c)return;ensureGraphPositions();let nodes=graphVisible().nodes;if(selectedOnly&&state.graphView.selected.length){const ss=new Set(state.graphView.selected);nodes=nodes.filter(n=>ss.has(n.id))}if(!nodes.length)return;let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;nodes.forEach(n=>{const p=state.graphView.positions[n.id];minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minY=Math.min(minY,p.y);maxY=Math.max(maxY,p.y)});const rect=c.getBoundingClientRect(),pad=80,ww=Math.max(80,maxX-minX),hh=Math.max(80,maxY-minY),scale=Math.max(.2,Math.min(3,Math.min((rect.width-pad)/ww,(rect.height-pad)/hh)));state.graphView.scale=scale;state.graphView.ox=rect.width/2-(minX+maxX)/2*scale;state.graphView.oy=rect.height/2-(minY+maxY)/2*scale;drawGraphCanvas()}
  function graphSelectedNode(){if(state.graphView.selected.length!==1)return null;return (state.graph?.nodes||[]).find(n=>n.id===state.graphView.selected[0])||null}
