  function graphContext(op){const node=graphSelectedNode(),sel=new Set(state.graphView.selected);if(op==='clear-hidden'){state.graphView.hidden={};state.graphView.collapsed={};drawGraphCanvas();return}if(op==='isolate'||op==='hide'){if(!sel.size)return;const keep=new Set(sel);(state.graph?.edges||[]).forEach(e=>{if(sel.has(e.from))keep.add(e.to);if(sel.has(e.to))keep.add(e.from)});const h={};(state.graph?.nodes||[]).forEach(n=>{if(!keep.has(n.id))h[n.id]=true});state.graphView.hidden=h;drawGraphCanvas();return}if(op==='collapse'){sel.forEach(id=>state.graphView.collapsed[id]=true);drawGraphCanvas();return}if(!node)return;if(op==='cluster-expand'){state.graphView.expandedCluster=node.meta?.cluster_key||'';state.graphView.focusID='';void reloadGraph(true);return}if(op==='cluster-collapse'){state.graphView.expandedCluster='';void reloadGraph(true);return}if(op==='neighbors'){state.graphView.focusID=node.id;state.graphView.neighbors=2;void reloadGraph(true);return}if(op==='focus'){state.graphView.focusID=node.id;state.graphView.neighbors=1;void reloadGraph(true);return}if(op==='traffic'||op==='flows'||op==='alerts'){const q=graphNodeFocusQuery(node);if(op==='flows')state.trafficMode='flows';setFocus(q,op==='alerts'?'#/security':'#/traffic');return}if(op==='asset'){const id=node.type==='ip'?'ip:'+node.label:node.type+':'+(node.type==='process'?(node.meta?.pid||node.id.split(':')[1]):node.label);location.hash='#/asset/'+encodeURIComponent(id)}}
  function graphApplyFilters(){const ids={q:'graphSearch',src:'graphSrc',dst:'graphDst',asset:'graphAsset',proto:'graphProto',port:'graphPort',app:'graphApp',severity:'graphSeverity',range:'graphRange'};for(const[k,id]of Object.entries(ids))state.graphView.filters[k]=$(id)?.value?.trim()||'';state.graphView.focusID='';state.graphView.expandedCluster='';void reloadGraph(true)}
  function renderInvestigation(){breadcrumb([['Investigation Graph','#/investigation']]);if(state.graph===null&&!state.loading.has('graph-v10'))void reloadGraph(true);const g=state.graph,f=state.graphView.filters,m=g?.meta||{};page.innerHTML=pageHead('Investigation Graph','High-density Canvas investigation workspace with server-side filtering, clustering, edge aggregation and bounded rendering.',`<button class="btn" data-action="graph-refresh">Refresh data</button>`)+`<section class="panel graph-control-panel"><div class="graph-filter-grid"><label>Search<input id="graphSearch" value="${attr(f.q||'')}" placeholder="IP, process, flow…"></label><label>Source IP<input id="graphSrc" value="${attr(f.src||'')}"></label><label>Destination IP<input id="graphDst" value="${attr(f.dst||'')}"></label><label>Asset<input id="graphAsset" value="${attr(f.asset||'')}"></label><label>Protocol<input id="graphProto" value="${attr(f.proto||'')}"></label><label>Port<input id="graphPort" type="number" min="1" max="65535" value="${attr(f.port||'')}"></label><label>Application<input id="graphApp" value="${attr(f.app||'')}"></label><label>Severity<select id="graphSeverity"><option value="">Any</option>${['critical','high','medium','low','info'].map(x=>`<option ${f.severity===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Time range<select id="graphRange">${['15m','1h','24h','all'].map(x=>`<option ${f.range===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn primary" data-action="graph-apply">Apply filters</button></div><div class="graph-toolbar"><button class="btn small" data-action="graph-view" data-op="zoom-in">＋ Zoom</button><button class="btn small" data-action="graph-view" data-op="zoom-out">− Zoom</button><button class="btn small" data-action="graph-view" data-op="fit">Fit to Screen</button><button class="btn small" data-action="graph-view" data-op="reset">Reset View</button><button class="btn small" data-action="graph-view" data-op="center">Center Graph</button><button class="btn small ${state.graphView.areaMode?'primary':''}" data-action="graph-view" data-op="area">▱ Area Select</button><button class="btn small" data-action="graph-context" data-op="clear-hidden">Show All</button><span>${m.visible_nodes||g?.nodes?.length||0}/${m.total_nodes||g?.nodes?.length||0} nodes · ${m.visible_edges||g?.edges?.length||0}/${m.total_edges||g?.edges?.length||0} edges ${m.clustered?'· clustered':''}${m.truncated?' · bounded':''}</span></div></section><div class="graph-workspace"><section class="panel graph-canvas-panel">${g?.nodes?.length?`<div class="graph-canvas-wrap"><canvas id="graphCanvas" class="investigation-canvas" aria-label="Interactive investigation graph"></canvas><div id="graphTooltip" class="graph-tooltip hidden"></div></div>`:empty(state.loading.has('graph-v10')?'Loading graph':'No graph evidence','Capture/replay traffic or broaden filters.')}</section><aside class="panel graph-detail-panel"><div class="panel-head"><div><div class="panel-title">Selection details</div><div class="panel-sub">Node/edge context and cross-console actions</div></div></div><div id="graphDetail" class="panel-body"></div></aside></div>`;if(g?.nodes?.length)requestAnimationFrame(initGraphCanvas)}
  function graphViewAction(op){if(op==='zoom-in'){state.graphView.scale=Math.min(4,state.graphView.scale*1.2);drawGraphCanvas()}else if(op==='zoom-out'){state.graphView.scale=Math.max(.2,state.graphView.scale*.83);drawGraphCanvas()}else if(op==='fit'||op==='center')fitGraph(false);else if(op==='reset'){state.graphView.scale=1;state.graphView.ox=0;state.graphView.oy=0;state.graphView.hidden={};state.graphView.collapsed={};drawGraphCanvas()}else if(op==='area'){state.graphView.areaMode=!state.graphView.areaMode;renderInvestigation()}}

