  function assetAction(op,id){const a=(state.soc.assets||[]).find(x=>x.id===id)||state.detailCache.get('asset:'+id);if(!a)return;if(op==='graph'){state.graphView.filters.asset=a.ip||a.name;state.graphView.focusID='';state.graph=null;location.hash='#/investigation';return}const q=assetFocus(a);if(op==='flows')state.trafficMode='flows';setFocus(q,op==='alerts'?'#/security':'#/traffic')}

  async function loadNotifications(){if(!can('admin:settings'))return;try{state.notifications=await api('/api/v1/notifications');if(route().name==='system')renderSystem()}catch(e){toast('Notification settings unavailable',e.message,'err')}}
  function notificationSev(prefix,selected){const set=new Set(selected||[]);return `<div class="check-grid">${['info','low','medium','high','critical'].map(x=>`<label><input type="checkbox" class="${prefix}-severity" value="${x}" ${set.has(x)?'checked':''}>${x==='info'?'Informational':x[0].toUpperCase()+x.slice(1)}</label>`).join('')}</div>`}
  function renderNotificationSettings(){if(!can('admin:settings'))return`<section class="panel"><div class="panel-body">Notification configuration is restricted to administrators.</div></section>`;const d=state.notifications;if(!d)return`<section class="panel">${empty('Loading Notifications','Reading encrypted Email/Telegram settings…')}</section>`;const e=d.email||{},t=d.telegram||{},mode=e.starttls?'starttls':e.ssl?'ssl':e.tls?'tls':'clear';return`<div class="section-title"><h2>Notifications</h2><span>Asynchronous · bounded queue · severity routing · cooldown/deduplication</span></div><div class="grid-equal"><section class="panel"><div class="panel-head"><div><div class="panel-title">Email / SMTP</div><div class="panel-sub">Secret password is encrypted at rest and never returned by the API.</div></div>${statePill(e.enabled?'enabled':'disabled')}</div><div class="panel-body admin-form"><label class="checkline full"><input id="notifEmailEnabled" type="checkbox" ${e.enabled?'checked':''}>Enable Email Notifications</label><label>SMTP Server<input id="notifSMTPHost" value="${attr(e.smtp_server||'')}"></label><label>Port<input id="notifSMTPPort" type="number" min="1" max="65535" value="${n(e.smtp_port)||587}"></label><label>Username<input id="notifSMTPUser" value="${attr(e.username||'')}"></label><label>Password<input id="notifSMTPPassword" type="password" value="" placeholder="${e.password_set?'Configured — leave blank to keep':'Enter SMTP password'}"></label><label>Sender Address<input id="notifSender" value="${attr(e.sender||'')}"></label><label>Recipients<input id="notifRecipients" value="${attr((e.recipients||[]).join(', '))}" placeholder="soc@example.com, ir@example.com"></label><label>TLS mode<select id="notifSMTPMode"><option value="clear" ${mode==='clear'?'selected':''}>Clear text</option><option value="starttls" ${mode==='starttls'?'selected':''}>STARTTLS</option><option value="tls" ${mode==='tls'?'selected':''}>TLS (implicit)</option><option value="ssl" ${mode==='ssl'?'selected':''}>SSL/TLS (implicit)</option></select></label><label>Connection Timeout (sec)<input id="notifSMTPTimeout" type="number" min="1" max="120" value="${n(e.timeout_seconds)||10}"></label><div class="full"><strong>Severity routing</strong>${notificationSev('email',e.severities)}</div><div class="full notification-stats">Sent ${n(d.email_stats?.sent)} · Failed ${n(d.email_stats?.failed)} · Dropped ${n(d.email_stats?.dropped)} · Deduplicated ${n(d.email_stats?.deduplicated)} · Queue ${n(d.email_stats?.queue_depth)}</div><div class="full form-actions"><button class="btn primary" data-action="notifications-save">Save Notifications</button><button class="btn" data-action="notifications-test" data-channel="email">Send Test Email</button></div>${mode==='clear'?'<div class="plain-warning full">⚠ Clear-text SMTP is not encrypted. Prefer STARTTLS or TLS/SSL.</div>':''}</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Telegram</div><div class="panel-sub">Bot Token is encrypted at rest and masked in UI/API responses.</div></div>${statePill(t.enabled?'enabled':'disabled')}</div><div class="panel-body admin-form"><label class="checkline full"><input id="notifTelegramEnabled" type="checkbox" ${t.enabled?'checked':''}>Enable Telegram Notifications</label><label class="full">Bot Token<input id="notifBotToken" type="password" value="" placeholder="${t.bot_token_set?'Configured — leave blank to keep':'123456:bot-token'}"></label><label>Chat ID<input id="notifChatID" value="${attr(t.chat_id||'')}"></label><label>Timeout (sec)<input id="notifTelegramTimeout" type="number" min="1" max="120" value="${n(t.timeout_seconds)||10}"></label><div class="full"><strong>Severity routing</strong>${notificationSev('telegram',t.severities)}</div><label>Cooldown / dedup (sec)<input id="notifCooldown" type="number" min="0" max="86400" value="${n(d.cooldown_seconds)||300}"></label><label>Retry count<input id="notifRetries" type="number" min="0" max="5" value="${n(d.max_retries)||3}"></label><div class="full notification-stats">Sent ${n(d.telegram_stats?.sent)} · Failed ${n(d.telegram_stats?.failed)} · Dropped ${n(d.telegram_stats?.dropped)} · Deduplicated ${n(d.telegram_stats?.deduplicated)} · Queue ${n(d.telegram_stats?.queue_depth)}</div><div class="full form-actions"><button class="btn primary" data-action="notifications-save">Save Notifications</button><button class="btn" data-action="notifications-test" data-channel="telegram">Send Test Message</button></div></div></section></div>`}
  async function saveNotifications(){const sevs=cls=>[...document.querySelectorAll('.'+cls+'-severity:checked')].map(x=>x.value),mode=$('notifSMTPMode')?.value||'clear';const body={cooldown_seconds:n($('notifCooldown')?.value)||300,max_retries:n($('notifRetries')?.value)||3,email:{enabled:!!$('notifEmailEnabled')?.checked,smtp_server:$('notifSMTPHost')?.value.trim(),smtp_port:n($('notifSMTPPort')?.value),username:$('notifSMTPUser')?.value.trim(),password:$('notifSMTPPassword')?.value||'',sender:$('notifSender')?.value.trim(),recipients:($('notifRecipients')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),tls:mode==='tls',ssl:mode==='ssl',starttls:mode==='starttls',timeout_seconds:n($('notifSMTPTimeout')?.value)||10,severities:sevs('email')},telegram:{enabled:!!$('notifTelegramEnabled')?.checked,bot_token:$('notifBotToken')?.value||'',chat_id:$('notifChatID')?.value.trim(),timeout_seconds:n($('notifTelegramTimeout')?.value)||10,severities:sevs('telegram')}};try{state.notifications=await api('/api/v1/notifications',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});renderSystem();toast('Notification settings saved','Secrets remain masked after save.','ok')}catch(e){toast('Notification settings failed',e.message,'err')}}
  async function testNotification(channel){try{const r=await api('/api/v1/notifications/test/'+channel,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});toast(channel==='email'?'Test email sent':'Test Telegram message sent',r.message||'Success','ok')}catch(e){toast('Notification test failed',e.message,'err')}}

  function trafficMetricKeys(){switch(state.liveTraffic.metric){case'bytes':return['in_bytes_sec','out_bytes_sec','bytes/s'];case'packets':return['in_packets_sec','out_packets_sec','packets/s'];case'flows':return['in_flows_sec','out_flows_sec','flows/s'];default:return['in_bits_sec','out_bits_sec','bits/s']}}
  function trafficFormat(v){const m=state.liveTraffic.metric;v=n(v);if(m==='bits'){const u=['bps','Kbps','Mbps','Gbps','Tbps'];let i=0;while(v>=1000&&i<u.length-1){v/=1000;i++}return`${v>=100?Math.round(v):v.toFixed(1)} ${u[i]}`}if(m==='bytes')return bytes(v,true);return`${v>=100?Math.round(v):v.toFixed(1)} ${m==='packets'?'pps':'flows/s'}`}
  async function loadTrafficHistory(force=false){const lt=state.liveTraffic;if(lt.loading||(!force&&lt.loadedRange===lt.range&&lt.points.length))return;lt.loading=true;try{const d=await api('/api/v1/traffic/history?range='+encodeURIComponent(lt.range));lt.points=(d.points||[]).slice(-600);lt.loadedRange=lt.range;if(route().name==='overview')requestAnimationFrame(()=>{drawLiveTraffic();wireLiveTrafficControls()})}catch(e){toast('Traffic history unavailable',e.message,'err')}finally{lt.loading=false}}
  function appendTrafficLive(p){if(!p||state.liveTraffic.paused)return;state.liveTraffic.current=p;const pts=state.liveTraffic.points,ts=new Date(p.time).getTime();if(!Number.isFinite(ts))return;const last=pts[pts.length-1];if(last&&Math.abs(new Date(last.time).getTime()-ts)<900)pts[pts.length-1]=p;else pts.push(p);while(pts.length>600)pts.shift();if(route().name==='overview')requestAnimationFrame(drawLiveTraffic)}
  function liveTrafficPanel(){const lt=state.liveTraffic,p=lt.current||{},keys=trafficMetricKeys(),pts=lt.points||[],peakIn=Math.max(0,...pts.map(x=>n(x[keys[0]]))),peakOut=Math.max(0,...pts.map(x=>n(x[keys[1]])));return`<section class="panel live-traffic-panel"><div class="panel-head"><div><div class="panel-title">Live IN / OUT Traffic</div><div class="panel-sub">Real packet metadata telemetry · server-side historical aggregation · bounded browser history</div></div><div class="traffic-controls"><select id="trafficMetric"><option value="bits" ${lt.metric==='bits'?'selected':''}>bits/sec</option><option value="bytes" ${lt.metric==='bytes'?'selected':''}>bytes/sec</option><option value="packets" ${lt.metric==='packets'?'selected':''}>packets/sec</option><option value="flows" ${lt.metric==='flows'?'selected':''}>flows/sec</option></select><select id="trafficRange">${['1m','5m','15m','1h','24h'].map(x=>`<option ${lt.range===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn small" data-action="traffic-pause">${lt.paused?'Resume Live':'Pause Live'}</button></div></div><div class="traffic-stat-strip"><span>IN <strong id="trafficCurrentIn">${trafficFormat(p[keys[0]])}</strong></span><span>OUT <strong id="trafficCurrentOut">${trafficFormat(p[keys[1]])}</strong></span><span>Peak IN <strong id="trafficPeakIn">${trafficFormat(peakIn)}</strong></span><span>Peak OUT <strong id="trafficPeakOut">${trafficFormat(peakOut)}</strong></span></div><div class="panel-body"><div class="chart-wrap traffic-history-wrap"><canvas id="liveTrafficChart" class="chart-canvas"></canvas><div id="trafficTooltip" class="traffic-tooltip hidden"></div></div></div></section>`}
  function drawLiveTraffic(){const c=$('liveTrafficChart');if(!c)return;const rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=Math.max(1,Math.round(rect.width*dpr));c.height=Math.max(1,Math.round(rect.height*dpr));const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const pts=state.liveTraffic.points||[],keys=trafficMetricKeys(),w=rect.width,h=rect.height,p={l:62,r:18,t:14,b:28},W=w-p.l-p.r,H=h-p.t-p.b,max=Math.max(1,...pts.flatMap(x=>[n(x[keys[0]]),n(x[keys[1]])]));ctx.clearRect(0,0,w,h);ctx.strokeStyle='#e7edf5';ctx.fillStyle='#738198';ctx.font='10px system-ui';ctx.textAlign='right';for(let i=0;i<5;i++){const y=p.t+H*i/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText(trafficFormat(max*(1-i/4)),p.l-7,y+3)}const draw=(key,color)=>{ctx.beginPath();pts.forEach((d,i)=>{const x=p.l+(pts.length<2?0:i/(pts.length-1))*W,y=p.t+H-n(d[key])/max*H;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=color;ctx.lineWidth=2.2;ctx.stroke()};draw(keys[0],'#0f9bb8');draw(keys[1],'#2463eb');ctx.textAlign='left';ctx.fillStyle='#738198';for(let i=0;i<5&&pts.length;i++){const idx=Math.round(i*(pts.length-1)/4),x=p.l+(idx/(Math.max(1,pts.length-1)))*W;ctx.fillText(new Date(pts[idx].time).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}),x-14,h-6)}if(state.liveTraffic.hover>=0&&pts[state.liveTraffic.hover]){const i=state.liveTraffic.hover,x=p.l+(i/Math.max(1,pts.length-1))*W;ctx.strokeStyle='#94a3b8';ctx.beginPath();ctx.moveTo(x,p.t);ctx.lineTo(x,p.t+H);ctx.stroke()};c.dataset.points=String(pts.length);c.dataset.metric=state.liveTraffic.metric;c.dataset.range=state.liveTraffic.range;const cur=state.liveTraffic.current||pts[pts.length-1]||{};const pi=Math.max(0,...pts.map(x=>n(x[keys[0]]))),po=Math.max(0,...pts.map(x=>n(x[keys[1]])));if($('trafficCurrentIn'))$('trafficCurrentIn').textContent=trafficFormat(cur[keys[0]]);if($('trafficCurrentOut'))$('trafficCurrentOut').textContent=trafficFormat(cur[keys[1]]);if($('trafficPeakIn'))$('trafficPeakIn').textContent=trafficFormat(pi);if($('trafficPeakOut'))$('trafficPeakOut').textContent=trafficFormat(po)}
  function wireLiveTrafficControls(){const c=$('liveTrafficChart');if(c&&!c.dataset.bound){c.dataset.bound='1';c.addEventListener('mousemove',e=>{const pts=state.liveTraffic.points||[];if(!pts.length)return;const r=c.getBoundingClientRect(),left=62,right=18,w=Math.max(1,r.width-left-right),x=Math.max(0,Math.min(w,e.clientX-r.left-left)),idx=Math.max(0,Math.min(pts.length-1,Math.round(x/w*(pts.length-1))));state.liveTraffic.hover=idx;const d=pts[idx],keys=trafficMetricKeys(),t=$('trafficTooltip');t.classList.remove('hidden');t.style.left=(e.clientX-r.left+12)+'px';t.style.top='16px';t.innerHTML=`<strong>${new Date(d.time).toLocaleString()}</strong><span>IN ${trafficFormat(d[keys[0]])}</span><span>OUT ${trafficFormat(d[keys[1]])}</span>`;drawLiveTraffic()});c.addEventListener('mouseleave',()=>{state.liveTraffic.hover=-1;$('trafficTooltip')?.classList.add('hidden');drawLiveTraffic()})}if($('trafficRange'))$('trafficRange').onchange=e=>{state.liveTraffic.range=e.target.value;state.liveTraffic.loadedRange='';void loadTrafficHistory(true)};if($('trafficMetric'))$('trafficMetric').onchange=e=>{state.liveTraffic.metric=e.target.value;drawLiveTraffic()}}


  function connect(){if(!state.authenticated)return;const proto=location.protocol==='https:'?'wss':'ws';const ws=new WebSocket(`${proto}://${location.host}/ws${apiSuffix}`);state.ws=ws;ws.onopen=()=>{state.connected=true;updateChrome()};ws.onmessage=e=>{try{acceptData(JSON.parse(e.data))}catch(err){console.warn('bad telemetry frame',err)}};ws.onerror=()=>ws.close();ws.onclose=()=>{if(state.ws===ws)state.ws=null;state.connected=false;if(state.authenticated)updateChrome();clearTimeout(state.reconnectTimer);if(state.authenticated)state.reconnectTimer=setTimeout(connect,1500)}}

